     * 校验完整路径：每段占用落在运营日内且不与已发布时隙重叠；不可行时记录拒绝原因并返回 null。
     */
    private Candidate evaluate(Deque<RouteSegment> path, int total, Instant dayStart,
                               Instant dayEnd, List<PublishedSlot> slots,
                               List<Map<String, Object>> rejections) {
        List<LegPlan> legs = new ArrayList<>(path.size());
        Instant cursor = null;
        for (RouteSegment segment : path) {
            Instant start = cursor == null ? null : cursor;
            start = start == null ? null : start;
            legs.add(new LegPlan(segment, null, null));
            cursor = cursor;
        }
        // 逐段重算时刻：首段起点为出发时刻
        legs.clear();
        Instant time = null;
        for (RouteSegment segment : path) {
            Instant start = time;
            Instant end = start.plusMinutes(segment.minutes());
            legs.add(new LegPlan(segment, start, end));
            time = end;
        }
        List<String> segmentIds = path.stream().map(RouteSegment::segmentId).toList();
        for (LegPlan leg : legs) {
            if (leg.startUtc().isBefore(dayStart) || leg.endUtc().isAfter(dayEnd)) {
                rejections.add(rejection("ROUTE_CROSS_DAY", segmentIds,
                        "路径跨 Asia/Shanghai 运营日"));
