        }
        Instant end = cursor.plusMinutes(segment.minutes());
        if (end.isAfter(arriveBy)) {
            continue;
        }
        int total = totalMinutes(path) + segment.minutes();
        if (best[0] != null && total > best[0].totalMinutes()) {
            continue;
        }
        path.addLast(segment);
        if (segment.toStation().equals(target)) {
            Candidate candidate = evaluate(path, total, dayStart, dayEnd, slots, rejections);
            if (candidate != null && (best[0] == null
                    || compare(candidate, best[0]) < 0)) {
                best[0] = candidate;
            }
        } else {
            visited.add(segment.toStation());
            dfs(segment.toStation(), target, end, arriveBy, dayStart, dayEnd, adjacency,
                    slots, visited, path, best, rejections);
            visited.remove(segment.toStation());
        }
        path.removeLast();
    }
}

